def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    # Dynamically import pathlib to avoid an explicit import statement
    Path = __import__('pathlib').Path

    try:
        p = Path(path)
    except Exception as e:
        return f'error: invalid path format ({e})'

    if not p.exists():
        return f'error: path does not exist'

    if p.is_file():
        return 'file'

    if p.is_dir():
        # If there is a file directly under this directory whose name starts with '0='
        # we consider it an OCFL object.  Otherwise, it's a storage root.
        try:
            for child in p.iterdir():
                if child.is_file() and child.name.startswith('0='):
                    return 'object'
        except Exception as e:
            return f'error: cannot list directory contents ({e})'
        return 'root'

    return 'error: unrecognized path type'

