def parse_arguments(*unparsed_arguments):
    '''Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.'''

    def _prepend_iterator(value, iterator):
        yield value
        yield from iterator

    def _make_namespace(tokens):
        ns = argparse.Namespace()
        it = iter(tokens)
        for token in it:
            if token.startswith('--') and len(token) > 2:
                key = token[2:].replace('-', '_')
                try:
                    val = next(it)
                    if val.startswith('-'):
                        setattr(ns, key, None)
                        it = _prepend_iterator(val, it)
                    else:
                        setattr(ns, key, val)
                except StopIteration:
                    setattr(ns, key, None)
            elif token.startswith('-') and len(token) > 1:
                # short option (e.g. -f)
                key = token[1:]
                try:
                    val = next(it)
                    if val.startswith('-'):
                        setattr(ns, key, None)
                        it = _prepend_iterator(val, it)
                    else:
                        setattr(ns, key, val)
                except StopIteration:
                    setattr(ns, key, None)
            else:
                # Positional value
                if hasattr(ns, 'positional'):
                    ns.positional.append(token)
                else:
                    ns.positional = [token]
        return ns

    args = list(unparsed_arguments)
    if not args:
        return {'global': argparse.Namespace()}

    # Find the first token that is not an option (doesn't start with '-') – treat this as a subparser command.
    subcmd_index = None
    skip_help = {'-h', '--help'}
    for i, token in enumerate(args):
        if not token.startswith('-') and token not in skip_help:
            subcmd_index = i
            break

    if subcmd_index is None:
        # No subcommand found, all are treated as global arguments.
        return {'global': _make_namespace(args)}

    global_tokens = args[:subcmd_index]
    subcmd_name = args[subcmd_index]
    subcmd_tokens = args[subcmd_index + 1:]

    return {
        'global': _make_namespace(global_tokens),
        subcmd_name: _make_namespace(subcmd_tokens)
    }

