import json, os, re, logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding
    parsed configuration, and sequence of logging.LogRecord instances containing any
    parse errors.
    """
    logger = logging.getLogger(__name__)
    configs = {}
    errors = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            return env_pattern.sub(lambda m: os.getenv(m.group(1), m.group(0)), value)
        if isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        if isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        return value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            config = json.loads(content)
            if resolve_env:
                config = resolve_env_vars(config)
            if overrides and isinstance(overrides, dict):
                config.update(overrides)
            configs[fname] = config
        except Exception as e:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse '{fname}': {e}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    return configs, errors

