def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    import xml.etree.ElementTree as ET

    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # First try JSON parsing
    try:
        data = json.loads(document)
        # Ensure 'aliases' is a list
        aliases = data.get("aliases", [])
        if isinstance(aliases, str):
            aliases = [aliases]
        data["aliases"] = aliases
        return data
    except json.JSONDecodeError:
        pass  # fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    aliases: list[str] = []
    public_key: str | None = None

    # Helper to strip namespace
    def local_name(tag: str) -> str:
        return tag.split("}")[-1].lower()

    for elem in root.iter():
        tag = local_name(elem.tag)
        if tag == "alias" and elem.text:
            aliases.append(elem.text.strip())
        elif tag == "link":
            href = elem.attrib.get("href")
            if href:
                aliases.append(href.strip())
        elif tag == "property":
            name = elem.attrib.get("name", "").lower()
            if "public-key" in name and elem.text:
                public_key = elem.text.strip()

    return {"aliases": aliases, "public_key": public_key}

