        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. Can be either a dict with keys
                     'value', 'min', 'max' or an iterable in the order
                     (value, min, max). Raises ValueError or TypeError if
                     validation fails.
        :return: True if the value is between min and max (inclusive),
                 False otherwise.
        """
        # Extract values
        if isinstance(args, dict):
            if not all(k in args for k in ("value", "min", "max")):
                raise ValueError("args dict must contain keys 'value', 'min', 'max'")
            value, min_val, max_val = args["value"], args["min"], args["max"]
        else:
            try:
                value, min_val, max_val = args
            except Exception:
                raise ValueError(
                    "args must be a dict with keys 'value', 'min', 'max' "
                    "or an iterable of the form (value, min, max)"
                )

        # Type checking
        for name, val in (("value", value), ("min", min_val), ("max", max_val)):
            if not isinstance(val, (int, float)):
                raise TypeError(f"{name} must be numeric, got {type(val).__name__}")

        # Logical sanity
        if min_val > max_val:
