def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    class ComplexType:
        """Container for a complex argument type."""

        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            # spec_option may contain detailed metadata about the option;
            # we store it verbatim and expose convenient attributes if possible.
            self.spec_option = spec_option
            # Common attributes that a specification might define.
            self.help = spec_option.get("help") if isinstance(spec_option, dict) else None
            self.required = spec_option.get("required") if isinstance(spec_option, dict) else False
            self.default = spec_option.get("default") if isinstance(spec_option, dict) else None
            # The raw type for the option if present.
            self.type = spec_option.get("type") if isinstance(spec_option, dict) else None

        def __repr__(self):
            return (
                f"<ComplexType name={self.type_name!r} option={self.option_name!r} "
                f"subcommand={self.subcommand!r} required={self.required!r}>"
            )

        def __hash__(self):
            return hash((self.subcommand, self.type_name, self.option_name))

        def __eq__(self, other):
            if not isinstance(other, ComplexType):
                return False
            return (
                self.subcommand == other.subcommand
                and self.type_name == other.type_name
                and self.option_name == other.option_name
            )

    # Return a new instance of the complex type.
    return ComplexType(subcommand, type_name, option_name, spec_option)

