    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Import needed modules inside the function
    import subprocess
    import json
    import shlex

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        # If verbose is an integer, convert it to N v's (-v, -vv, -vvv)
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * min(verbose, 3))
        else:
            # Assume string like 'vv' or 'v'
            if isinstance(verbose, str) and verbose.strip():
                # Count 'v's but limit to 3
                v_count = min(verbose.count('v'), 3)
                if v_count > 0:
                    cmd.append("-" + "v" * v_count)

    # Extra variables
    if extra_vars:
        try:
            # Convert dict to JSON string for Ansible
            ev_str = json.dumps(extra_vars, separators=(",", ":"))
        except Exception:
            # Fallback: convert to key=value pairs
            ev_parts = []
            for k, v in extra_vars.items():
                ev_parts.append(f"{k}={v}")
            ev_str = " ".join(ev_parts)
        cmd.extend(["--extra-vars", ev_str])

    # Additional ansible playbook args
    if ansible_args:
        for key, value in ansible_args.items():
            # Skip None values
            if value is None:
                continue
            # Build argument flag
            if isinstance(key, str) and key.startswith("--"):
                flag = key
            elif isinstance(key, str) and key.startswith("-"):
                flag = key
            else:
                flag = f"--{key}"
            # Handle boolean flags
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # Skip if False
                continue
            # Handle list values as comma-separated
            if isinstance(value, (list, tuple, set)):
                flag_value = ",".join(map(str, value))
            else:
                flag_value = str(value)
            cmd.extend([flag, flag_value])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            check=True,
            capture_output=True,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        # If the plugin has a logger, use it to log error
        if hasattr(ir_plugin, "log"):
            ir_plugin.log(f"ansible-playbook failed: {exc.stderr}")
        raise

    # Log the output if possible
    if hasattr(ir_plugin, "log"):
        ir_plugin.log(result.stdout)
        if result.stderr:
            ir_plugin.log(result.stderr)

    return result

